const run = async (id, work) => {
  const at = new Date().toISOString();
  try { const detail = await work(); rows.push({ id, result: 'PASS', at, detail }); console.log(`${id} PASS ${detail}`); }
  catch (e) { rows.push({ id, result: 'FAIL', at, detail: e.message }); console.log(`${id} FAIL ${e.message}`); }
};
